section.script:
(function () {
    const key = 'partner_courier_accounting_login';
    const form = document.querySelector('.ca-login-card form');
    const courierInput = document.getElementById('ca_login_courier_id');
    const identityInput = document.getElementById('ca_login_identity_no');
    const rememberInput = document.getElementById('ca_login_remember');
    if (!form || !courierInput || !identityInput || !rememberInput) return;
    try {
        const saved = JSON.parse(window.localStorage.getItem(key) || '{}');
        if (saved.courier_id || saved.identity_no) {
            courierInput.value = saved.courier_id || '';
            identityInput.value = saved.identity_no || '';
            rememberInput.checked = true;
        }
    } catch (error) {}
    form.addEventListener('submit', function () {
        if (rememberInput.checked) {
            window.localStorage.setItem(key, JSON.stringify({
                courier_id: courierInput.value || '',
                identity_no: identityInput.value || ''
            }));
        } else {
            window.localStorage.removeItem(key);
        }
    });
})();

(function () {
    const homeCard = document.querySelector('.ca-home-card');
    const contactId = homeCard ? parseInt(homeCard.dataset.contactId, 10) : 0;
    const userId = homeCard ? parseInt(homeCard.dataset.userId, 10) : 0;
    if (!contactId || !window.ReactNativeWebView) return;
    window.ReactNativeWebView.postMessage(JSON.stringify({
        type: 'USER_LOGGED_IN',
        userId: userId || false,
        contactId: contactId
    }));
})();

t.script:
(function () {
    document.querySelectorAll('.ca-call-button').forEach((button) => {
        button.addEventListener('click', function (event) {
            const phoneUrl = button.dataset.phoneUrl || button.getAttribute('href');
            if (!phoneUrl) return;
            event.preventDefault();
            window.location.href = phoneUrl;
        });
    });
})();

(function () {
    const modal = document.getElementById('caInfoModal');
    const title = document.getElementById('caInfoTitle');
    const text = document.getElementById('caInfoText');
    if (!modal || !title || !text) return;
    const close = () => {
        modal.classList.remove('is-open');
        modal.setAttribute('aria-hidden', 'true');
    };
    document.querySelectorAll('.ca-info-btn').forEach((button) => {
        button.addEventListener('click', () => {
            title.textContent = button.dataset.title || '';
            text.textContent = button.dataset.info || '';
            modal.classList.add('is-open');
            modal.setAttribute('aria-hidden', 'false');
        });
    });
    modal.querySelector('.ca-modal-close').addEventListener('click', close);
    modal.addEventListener('click', (event) => {
        if (event.target === modal) close();
    });
    document.addEventListener('keydown', (event) => {
        if (event.key === 'Escape') close();
    });
})();

(function () {
    const forms = document.querySelectorAll('.ca-upload-form');
    forms.forEach((form) => {
        form.addEventListener('submit', function (e) {
            const btn = form.querySelector('.ca-upload-btn');
            if (btn) {
                btn.disabled = true;
                btn.replaceChildren();
                const spinner = document.createElement('span');
                spinner.className = 'ca-spinner';
                btn.appendChild(spinner);
                const text = document.createTextNode(' Yükleniyor...');
                btn.appendChild(text);
            }
        });
    });
})();

(function () {
    const form = document.querySelector('.ca-request-form');
    if (form) {
        form.addEventListener('submit', function () {
            const btn = form.querySelector('.ca-submit-btn');
            if (btn) {
                btn.disabled = true;
                btn.replaceChildren();
                const spinner = document.createElement('span');
                spinner.className = 'ca-spinner';
                btn.appendChild(spinner);
                const text = document.createTextNode(' Gönderiliyor...');
                btn.appendChild(text);
            }
        });
    }
})();
